#!/usr/bin/env bash
date=$(date "+%Y-%m-%d")
echo $date
export password=[DB_PASSWORD]
echo $password


HADOOP_USER_NAME=hduser0506 sqoop import -D mapred.job.queue.name=queue_0506_01 --connect jdbc:mysql://127.0.0.1:3306/qualitis_gzpc_bdp_sit_01 --username qualitis_gzpc_bdp_sit --password $password --query "select DISTINCT department_code from qualitis_auth_department where department_code is not null AND \$CONDITIONS" --split-by department_code --fields-terminated-by "\t" --lines-terminated-by "\n"  --hive-import --hive-overwrite  --hive-database tctp_datashapis_ods_safe --hive-table qualitis_application_deptment --columns "department_code"  --compress --compression-codec org.apache.hadoop.io.compress.SnappyCodec --hive-drop-import-delims --target-dir /apps-data/hduser0506/qualitis_application_deptment --delete-target-dir

test1=`hive -S -e "set system:user.name=hduser0506;set mapreduce.job.queuename=queue_0506_01;select department_code from tctp_datashapis_ods_safe.qualitis_application_deptment where department_code is not null;"`
test1=`echo ${test1}`

echo '--------------------'
echo ${test1}

for element in ${test1[@]}
do
HADOOP_USER_NAME=hduser0506 sqoop import -D mapred.job.queue.name=queue_0506_01 --connect jdbc:mysql://127.0.0.1:3306/qualitis_gzpc_bdp_sit_01 --username qualitis_gzpc_bdp_sit --password $password --query "select a.id,a.rule_size,a.submit_time,a.finish_time,a.status,a.finish_task_num,a.fail_task_num,a.not_pass_task_num,a.invoke_type,a.exception_message,a.project_id,a.rule_group_name,a.rule_group_id,a.create_user,a.execute_user,a.filter_partition,a.startup_param,a.execution_param,a.run_date,d.rule_id,d.rule_name,e.cluster_name,e.database_name,e.table_name,e.col_name,g.name,g.department_code,a.run_date as ds,e.cluster_name as cluster from  qualitis_application a left join  qualitis_application_task c on a.id=c.application_id left join  qualitis_application_task_rule_simple d on c.id=d.task_id left join  qualitis_application_task_datasource  e on c.id=e.task_id left join  qualitis_auth_user  f on a.create_user =f.username left join  qualitis_auth_department  g on f.department_id =g.id where 1=1 and d.rule_id in (select  pu.rule_id  from qualitis_application_task_datasource pu) and exists(select b.id from qualitis_project_user b where a.project_id=b.project_id) and g.department_code is not null and g.department_code=$element and (a.submit_time >= (SELECT CAST((CAST(SYSDATE()AS DATE) - INTERVAL 1 DAY)AS DATETIME)) and a.submit_time< (SELECT CAST(CAST(SYSDATE()AS DATE)AS DATETIME)) )  AND \$CONDITIONS" --split-by a.submit_time --fields-terminated-by "\t" --lines-terminated-by "\n"  --hive-import --hive-overwrite  --hive-database tctp_datashapis_ods_safe --hive-table qualitis_application_detail_dm_$element --columns "id,rule_size,submit_time,finish_time,status,finish_task_num,fail_task_num,not_pass_task_num,invoke_type,exception_message,project_id,rule_group_name,rule_group_id,create_user,execute_user,filter_partition,startup_param,execution_param,run_date,rule_id,rule_name,cluster_name,database_name,table_name,col_name,name,department_code"  --hive-partition-key ds,cluster  --hive-partition-value $date,"BDP_Cluster" --compress --compression-codec org.apache.hadoop.io.compress.SnappyCodec --hive-drop-import-delims --target-dir /apps-data/hduser0506/qualitis_application_detail_dm_$element --delete-target-dir
done


HADOOP_USER_NAME=hduser0506 sqoop import -D mapred.job.queue.name=queue_0506_01 --connect jdbc:mysql://127.0.0.1:3306/qualitis_gzpc_bdp_sit_01 --username qualitis_gzpc_bdp_sit --password $password --query "select a.id,a.rule_size,a.submit_time,a.finish_time,a.status,a.finish_task_num,a.fail_task_num,a.not_pass_task_num,a.invoke_type,a.exception_message,a.project_id,a.rule_group_name,a.rule_group_id,a.create_user,a.execute_user,a.filter_partition,a.startup_param,a.execution_param,a.run_date,d.rule_id,d.rule_name,e.cluster_name,e.database_name,e.table_name,e.col_name,g.name,g.department_code,a.run_date as ds,e.cluster_name as cluster from  qualitis_application a left join  qualitis_application_task c on a.id=c.application_id left join  qualitis_application_task_rule_simple d on c.id=d.task_id left join  qualitis_application_task_datasource  e on c.id=e.task_id left join  qualitis_auth_user  f on a.create_user =f.username left join  qualitis_auth_department  g on f.department_id =g.id where 1=1 and d.rule_id in (select  pu.rule_id  from qualitis_application_task_datasource pu) and exists(select b.id from qualitis_project_user b where a.project_id=b.project_id) and g.department_code is not null and (a.submit_time >= (SELECT CAST((CAST(SYSDATE()AS DATE) - INTERVAL 1 DAY)AS DATETIME)) and a.submit_time< (SELECT CAST(CAST(SYSDATE()AS DATE)AS DATETIME)) ) AND \$CONDITIONS" --split-by a.submit_time --fields-terminated-by "\t" --lines-terminated-by "\n"  --hive-import --hive-overwrite  --hive-database tctp_datashapis_ods_safe --hive-table qualitis_application_detail_ods --columns "id,rule_size,submit_time,finish_time,status,finish_task_num,fail_task_num,not_pass_task_num,invoke_type,exception_message,project_id,rule_group_name,rule_group_id,create_user,execute_user,filter_partition,startup_param,execution_param,run_date,rule_id,rule_name,cluster_name,database_name,table_name,col_name,name,department_code"  --hive-partition-key ds,cluster  --hive-partition-value $date,"BDP_Cluster" --compress --compression-codec org.apache.hadoop.io.compress.SnappyCodec --hive-drop-import-delims --target-dir /apps-data/hduser0506/qualitis_application_detail_ods --delete-target-dir





